function clone(x){return JSON.parse(JSON.stringify(x));}
function generateBank(seed='EDO-C3-2026'){const b=BANK.map(clone);b.forEach(q=>q.seed=seed);return b;}
function generateFamily(seed,id){const q=BANK.find(x=>x.id===id);if(!q)return null;const z=clone(q);z.seed=seed;return z;}
function normalize(s){return String(s).toLowerCase().replace(/\s+/g,' ').trim();}
function validateBank(bank){const errors=[],ids=new Set(),types={};for(const q of bank){if(ids.has(q.id))errors.push(`ID repetido ${q.id}`);ids.add(q.id);types[q.type]=(types[q.type]||0)+1;if(!BASE.TOPIC_LABEL[q.topic])errors.push(`${q.id}: tema inválido`);if(!q.source||!q.prompt||!q.hint||!q.explanation)errors.push(`${q.id}: campo académico incompleto`);if(!TYPE_LABELS[q.type])errors.push(`${q.id}: tipo inválido`);if(['multiple_choice','statements','ordering','graphic'].includes(q.type)){if(!Array.isArray(q.choices)||q.choices.length!==6)errors.push(`${q.id}: debe tener 6 opciones`);if(new Set((q.choices||[]).map(normalize)).size!==6)errors.push(`${q.id}: opciones duplicadas`);if(!(q.answer&&Number.isInteger(q.answer.index)&&q.answer.index>=0&&q.answer.index<6))errors.push(`${q.id}: respuesta inválida`);}if(q.type==='numeric'&&(!Number.isSafeInteger(q.answer?.value)||q.answer?.tolerance!==0))errors.push(`${q.id}: numérico no entero exacto`);if(q.type==='true_false'&&typeof q.answer?.value!=='boolean')errors.push(`${q.id}: V/F inválido`);if(q.graphic&&!BASE.GRAPHICS[q.graphic])errors.push(`${q.id}: gráfica inexistente ${q.graphic}`);}if(bank.length!==500)errors.push(`Cantidad esperada 500, obtenida ${bank.length}`);const target={"multiple_choice": 125, "true_false": 75, "numeric": 75, "statements": 75, "ordering": 75, "graphic": 75};for(const [t,n] of Object.entries(target))if(types[t]!==n)errors.push(`Tipo ${t}: esperado ${n}, obtenido ${types[t]||0}`);return errors;}
window.ECOMAT_EXTENDED={...BASE,TYPE_LABELS,MODE_LABELS,generateBank,generateFamily,validateBank,normalize,EXPANDED_COUNT:500,TYPE_TARGETS:{"multiple_choice": 125, "true_false": 75, "numeric": 75, "statements": 75, "ordering": 75, "graphic": 75}};
